\mathrm{Inv}_{\mathcal C}:\mathrm{IsoMor}_{\mathcal C}\to\mathrm{IsoMor}_{\mathcal C},\\
\mathrm{Inv}_{\mathcal C}(u)\coloneqq\iota v\in\mathrm{Hom}_{\mathcal C}(\mathrm{cod}_{\mathcal C}(u),\mathrm{dom}_{\mathcal C}(u))\ 
\bigl(v\circ u=\mathrm{id}_{\mathcal C}(\mathrm{dom}_{\mathcal C}(u))\land u\circ v=\mathrm{id}_{\mathcal C}(\mathrm{cod}_{\mathcal C}(u))\bigr),\\
u^{-1}\coloneqq\mathrm{Inv}_{\mathcal C}(u)\qquad(u\in\mathrm{IsoMor}_{\mathcal C}).
\end{gathered}
